mapper.select:
select DISTINCT FP.FINPROD_MARKET_ID id, IFNULL(p.FINPROD_ABBR,FP.FINPROD_ABBR) text, IFNULL(p.FINPROD_ID,FP.FINPROD_ID) object, (CASE WHEN FPA.DEAL_MODE =#{dealMode_10,jdbcType=VARCHAR} THEN #{yeOrNO_N,jdbcType=VARCHAR} ELSE FPA.IS_LAY END) col
from FIN_CASH_PAY_RULE FCPR, FIN_CASH_INFO FCI, FIN_PRODUCT FP INNER JOIN PTL_MANAGE_OBJ PMO ON (PMO.MANAGE_OBJ_ID = FP.FINPROD_ID or PMO.MANAGE_OBJ_ID= FP.P_FINPROD_ID) INNER JOIN FIN_PRODUCT_ADD D2 ON FP.FINPROD_ID = D2.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PMO.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT P ON FP.P_FINPROD_ID = P.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON FPA.FINPROD_ID = P.FINPROD_ID and P.PROFIT_TYPE = #{PROFIT_TYPE_01} where FP.FINPROD_ID = FCPR.FINPROD_ID AND FCPR.PAY_CYCLE != #{payCycle,jdbcType=VARCHAR} AND FP.FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR} AND FCI.CASH_ID = FCPR.CASH_ID AND FCI.CASH_TYPE_1 = #{cashType1}
AND (FP.FINPROD_MARKET_ID like concat('%',#{search},'%') OR FP.FINPROD_ABBR like concat('%',#{search},'%') OR FP.P_FINPROD_ID like concat('%',#{search},'%' ) )
AND FP.FINPROD_MARKET_ID = #{initValue}
AND ((FP.PROFIT_TYPE != #{PROFIT_TYPE_02} and ((P.FINPROD_ID IS NOT NULL and D2.deal_mode != #{dealMode_01,jdbcType=VARCHAR}) or D2.deal_mode = #{dealMode_01,jdbcType=VARCHAR})) OR FP.PROFIT_TYPE = #{PROFIT_TYPE_02})

select FIN_PRODUCT.FINPROD_MARKET_ID id, FIN_PRODUCT.FINPROD_ABBR text, CONCAT_WS('', FIN_PRODUCT.FINPROD_ID , ',' , DATE_FORMAT(FIN_PRODUCT.VDATE,'%Y-%m-%d') , ',' , DATE_FORMAT(FIN_PRODUCT.MDATE,'%Y-%m-%d') , ',' , FIN_PRODUCT.PROFIT_TYPE , ',' , FIN_PRODUCT.CALENDAR_ID , ',' , DATE_FORMAT(FIN_PRODUCT.LIQUIDATION_DATE,'%Y-%m-%d') ) object, case when FIN_PRODUCT.PROFIT_TYPE = #{profitType_02} then #{YES_OR_NO_N} when FIN_PRODUCT_ADD.DEAL_MODE = #{dealMode_10} then #{YES_OR_NO_N} else FIN_PRODUCT_ADD.IS_LAY end as col
from FIN_PRODUCT INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
INNER JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID AND FIN_PRODUCT_ADD.ISSUE_STATUS = #{ISSUE_STATUS_01}
FIN_PRODUCT.FINPROD_TYPE2 = #{args0,jdbcType=VARCHAR}
AND (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',#{search,jdbcType=VARCHAR},'%') OR FIN_PRODUCT.FINPROD_ABBR like concat('%',#{search,jdbcType=VARCHAR},'%'))
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{initValue}

SELECT distinct PLP.PROD_STYLE text, FP.FINPROD_ID id, CONCAT_WS('', FP.FINPROD_ID , ',' , DATE_FORMAT(FP.VDATE,'%Y-%m-%d') , ',' , DATE_FORMAT(FP.MDATE,'%Y-%m-%d') , ',' , FP.PROFIT_TYPE , ',' , FP.CALENDAR_ID , ',' , DATE_FORMAT(FP.LIQUIDATION_DATE,'%Y-%m-%d') ) object FROM PRD_LAYER_PARAM PLP,FIN_CASH_INFO FCI,FIN_PRODUCT FP WHERE PLP.FINPROD_ID = FCI.FINPROD_ID AND FCI.CASH_TYPE_1 =#{cashType1_03} AND PLP.FINPROD_ID = FP.FINPROD_ID
AND PLP.P_FINPROD_ID = #{pfinprodId}
AND (FP.FINPROD_ABBR like concat('%',#{search,jdbcType=VARCHAR},'%') OR PLP.PROD_STYLE like concat('%',#{search,jdbcType=VARCHAR},'%'))
AND PLP.FINPROD_ID = #{initValue}
